// Doksanland Gündem desk — first gate.
// A Türkiye trend list is mostly politics and football, so this is deliberately blunt.
// It is only the CHEAP gate: it catches obvious words, but it cannot know that
// "Ömer Bolat" is a minister or that "Çaykur Rizespor" is a club. The desk's own
// judgement (next node) is the real gate, and it must refuse anything it cannot place.

const BLOCK = [
  // politics and state
  'cumhurbaşkan','başbakan','bakan','meclis','parti','akp','chp','mhp','iyi parti','dem parti','seçim','siyaset','belediye','vali','asker','savaş','operasyon','şehit','terör','mavi vatan','gazze','israil','ukrayna','rusya','suriye',
  // religion
  'imam','cami','namaz','oruç','ramazan','kurban','dua','ayet','hadis','diyanet','hac','umre',
  // money
  'dolar','euro','altın','enflasyon','zam','faiz','asgari ücret','kira','ekonomi','maaş','vergi','iflas','kriz','borsa','bitcoin','kredi','indirim','ucuz','pahalı','fiyat',
  // harm and tragedy
  'hayatını kaybetti','ifşa','aldat','boşan','dolandırıc','kavga','savunma','gözyaşı','öldü','ölüm','vefat','cenaze','kaza','deprem','sel','yangın','cinayet','tecavüz','taciz','şiddet','gözaltı','tutukland','dava','mahkeme','savcı','hastane','kanser','intihar','hasta',
  // sport (clubs, bodies and the vocabulary around them)
  'fenerbahçe','galatasaray','beşiktaş','trabzonspor','başakşehir','rizespor','konyaspor','antalyaspor','alanyaspor','kasımpaşa','göztepe','samsunspor','gaziantep fk','eyüpspor','bodrum fk','sivasspor','kayserispor','hatayspor','adana demirspor','pendikspor','spor','futbol','basketbol','maç','transfer','hakem','penaltı','süper lig','puan durumu','şampiyonlar ligi','tff','derbi','teknik direktör',
  // vice
  'bahis','kumar','iddaa','porno','seks','alkol','rakı','bira','şarap','sigara'
];

const seen = $getWorkflowStaticData('global');
seen.titles = Array.isArray(seen.titles) ? seen.titles : [];

const norm = (s) => (s || '').toLocaleLowerCase('tr');
const survivors = [];

for (const item of $input.all()) {
  const title = item.json.title || '';
  const t = norm(title);
  if (!title) continue;
  if (BLOCK.some((w) => t.includes(w))) continue;   // obvious off-limits
  if (seen.titles.includes(t)) continue;             // already covered
  survivors.push(title);
}

if (seen.titles.length > 400) seen.titles = seen.titles.slice(-200);
if (survivors.length === 0) return [];

// Hand the desk a shortlist and let it choose, rather than forcing the first one.
const candidates = survivors.slice(0, 6);
for (const c of candidates) seen.titles.push(norm(c));

return [{ json: { candidates, checkedAt: new Date().toISOString() } }];

