parameters.jsCode:
// Read the desk's JSON, refuse anything it declined, and build the visual spec.

const raw = $json?.content?.[0]?.text || '';
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error('Desk did not return JSON: ' + raw.slice(0, 300));

const d = JSON.parse(match[0]);
const candidates = $('Gate and pick').first().json.candidates;

if (d.uygun === false || !d.hook || !d.caption_tr) {
  return [{ json: { skipped: true, topic: candidates.join(' / '), reason: d.ret_sebebi || 'desk declined' } }];
}

const id = 'gundem-' + new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
const palette = ['plum', 'cream', 'yellow', 'coral', 'teal'];

return [{ json: {
  skipped: false,
  id,
  topic: d.secilen_konu || candidates[0],
  hook: d.hook,
  caption_tr: d.caption_tr,
  needsCheck: d.dogrulanacak || [],
  visual: {
    id,
    format: 'post',
    kind: 'cover',
    bg: palette.includes(d.renk) ? d.renk : 'plum',
    kicker: 'Doksanland Bülteni',
    title: d.hook,
    sub: d.alt_satir || '',
    vhs: false
  }
} }];

