// Approved. Hand to the publisher.
// Instagram fetches images from a PUBLIC url, so the image is pushed to the repo's
// publish-media branch first and posted from its raw.githubusercontent address.
// Wire DOK-30 Publisher here once the media branch is connected.
const v = $('Build the visual').first().json;
return [{ json: { status: 'approved', id: v.id, topic: v.topic, caption_tr: v.caption_tr, visual: v.visual, approvedAt: new Date().toISOString() } }];

// Stopped by Bertuğ, or refused by the desk. Nothing goes out.
const v = $('Build the visual').first().json;
return [{ json: { status: 'stopped', id: v.id || null, topic: v.topic || null, reason: v.reason || 'rejected on Telegram', at: new Date().toISOString() } }];
